import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { HeartPulse } from 'lucide-react';

// Upgraded temporary database storing names, emails, and passwords
const registeredUsers = [
  { name: "Demo User", email: "test@example.com", password: "password123" },
  { name: "Admin", email: "admin@health.com", password: "admin" }
];

function Login({ setUser }) {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({ name: '', email: '', password: '' });
  const [authError, setAuthError] = useState('');
  const navigate = useNavigate();

  const onSubmit = (e) => {
    e.preventDefault();
    setAuthError('');

    if (isLogin) {
      // 1. Check if the email exists
      const existingUser = registeredUsers.find(user => user.email === formData.email);
      
      if (!existingUser) {
        setAuthError("Email not found. Please switch to Sign Up to create an account.");
        return;
      }

      // 2. Check if the password matches
      if (existingUser.password !== formData.password) {
        setAuthError("Incorrect password. Please try again.");
        return;
      }

      // 3. Login successful
      setUser({ name: existingUser.name, email: existingUser.email });
    } else {
      // Handle Sign Up
      const existingUser = registeredUsers.find(user => user.email === formData.email);
      
      if (existingUser) {
        setAuthError("An account with this email already exists. Please log in.");
        return;
      }

      // Save new user to temporary database
      registeredUsers.push({
        name: formData.name,
        email: formData.email,
        password: formData.password
      });
      
      setUser({ name: formData.name, email: formData.email });
    }
    
    navigate('/');
  };

  return (
    <div className="max-w-md mx-auto mt-10">
      <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="bg-blue-600 p-6 text-center">
          <HeartPulse size={40} className="mx-auto text-blue-200 mb-2" />
          <h2 className="text-2xl font-bold text-white">{isLogin ? 'Welcome Back' : 'Create an Account'}</h2>
        </div>
        
        <div className="p-8">
          {authError && (
            <div className="mb-4 text-red-500 text-sm font-bold p-3 bg-red-50 rounded border border-red-100">
              {authError}
            </div>
          )}
          
          <form onSubmit={onSubmit} className="space-y-4">
            {!isLogin && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                <input 
                  type="text" required 
                  className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                />
              </div>
            )}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
              <input 
                type="email" required 
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.email}
                onChange={e => setFormData({...formData, email: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
              <input 
                type="password" required 
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.password}
                onChange={e => setFormData({...formData, password: e.target.value})}
              />
            </div>

            <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded-lg hover:bg-blue-700 mt-4 transition shadow-md">
              {isLogin ? 'Sign In' : 'Register'}
            </button>
          </form>

          <div className="mt-6 text-center text-sm text-gray-600">
            {isLogin ? "Don't have an account? " : "Already have an account? "}
            <button 
              onClick={() => { 
                setIsLogin(!isLogin); 
                setAuthError(''); 
                setFormData({ name: '', email: '', password: '' }); // Clear form on switch
              }} 
              className="text-blue-600 font-bold hover:underline"
            >
              {isLogin ? 'Sign up here' : 'Log in here'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Login;
